def-hyp[predicate](
    __list__(Type.annotation(@X, Set(P@Set.def.order.partial)), Type.annotation(@a, P@Set.def.order.partial)),
    Set.order.greatest(a, X, P@Set.def.order.partial),
    Logic.and(
        Set.mem(a, X),
        Logic.forall-typed(@x, X, Logic.or(Rl.apply($\lt$@Set.def.order.partial, x, a), Eq(x, a)))
    )
)
